96	struct ScheduleGroupIdent {
97	  size_t asc_graph_id{0L};   // AscGraph的ID
98	  size_t impl_graph_id{0L};  // ImplGraph的ID
99	  size_t group_id{0L};       // ScheduleGroup的ID
100	  bool operator<(const ScheduleGroupIdent &other) const {
101	    if (impl_graph_id < other.impl_graph_id) {
102	      return true;
103	    } else if (impl_graph_id > other.impl_graph_id) {
104	      return false;
105	    }
106	    // 如果 impl_graph_id 相等，则比较 group_id
107	    return group_id < other.group_id;
108	  }
109	  bool operator==(const ScheduleGroupIdent &other) const {
110	    return (impl_graph_id == other.impl_graph_id) && (group_id == other.group_id);
111	  }
112	  bool operator!=(const ScheduleGroupIdent &other) const {
113	    return (impl_graph_id != other.impl_graph_id) || (group_id != other.group_id);
114	  }
115	  [[nodiscard]] std::string GetGroupPrefix() const {
116	    return "AscGraph" + std::to_string(asc_graph_id) + "ScheduleResult" + std::to_string(impl_graph_id) + "G" +
117	           std::to_string(group_id);
118	  }
119	  // 小写加短下划线风格：snake_case
120	  [[nodiscard]] std::string GetGroupPrefixSnakeCase() const {
121	    return "asc_graph" + std::to_string(asc_graph_id) + "_schedule_result" + std::to_string(impl_graph_id) + "_g" +
122	           std::to_string(group_id);
123	  }
124	  [[nodiscard]] std::string GetItemPrefix() const {
125	    return "graph" + std::to_string(asc_graph_id) + "_result" + std::to_string(impl_graph_id) + "_g" +
126	           std::to_string(group_id);
127	  }
128	};
