130	struct ReuseScheduleGroupInfo {
131	  std::vector<std::string> reuse_input_axes;   // 复用的schedule group内所有输入轴名称
132	  std::vector<std::string> reuse_search_axes;  // 复用的schedule group内所有求解轴名称
133	  std::vector<uint32_t> tiling_keys;           // 复用的schedule group内对应的tiling key
134	};
135	struct ReuseScheduleGroup {
136	  ScheduleGroupIdent reuse_group_ident;  // 复用的schedule group信息
137	  ReuseScheduleGroupInfo info;
138	  std::map<ScheduleGroupIdent, ReuseScheduleGroupInfo>
139	      schedule_group_to_info;  // 所有schedule group对应的轴名称，映射的轴与reuse_axes对应
140	  bool IsReuseGroup(const ScheduleGroupIdent &schedule_group_ident) const {
141	    if (reuse_group_ident == schedule_group_ident) {
142	      return false;
143	    }
144	    const auto &iter = schedule_group_to_info.find(schedule_group_ident);
145	    if (iter == schedule_group_to_info.end()) {
146	      return false;
147	    }
148	    return (info.reuse_search_axes.size() == iter->second.reuse_search_axes.size()) &&
149	           (info.reuse_input_axes.size() == iter->second.reuse_input_axes.size()) &&
150	           (info.tiling_keys.size() == iter->second.tiling_keys.size());
151	  }
152	};
