171	// Model 级别的 Tiling 调度配置
172	struct TilingScheduleConfig {
173	  // 多核UB权衡配置
174	  TradeOffConfig trade_off_config;
175	
176	  // CacheLine 大小（字节）
177	  uint32_t cache_line_size{arch_param::kDefaultCacheLineSize};
178	
179	  // Vector length 大小（字节）
180	  uint32_t vector_len_size{arch_param::kDefaultVectorLenSize};
181	
182	  // 是否启用惩罚配置（用于日志区分）
183	  bool is_penalty_config{false};
184	
185	  [[nodiscard]] std::string DebugString() const {
186	    return "trade_off_config: {" + trade_off_config.DebugString() +
187	           "}, cache_line_size: " + std::to_string(cache_line_size) +
188	           ", vector_len_size: " + std::to_string(vector_len_size) +
189	           ", is_penalty_config: " + std::to_string(is_penalty_config);
190	  }
191	};
