193	enum class CacheLineDirection : uint8_t {
194	  kUnknown = 0,
195	  kGmToUb = 1,
196	  kUbToGm = 2,
197	};
198	
199	// Contract: In non-PGO group-parallel path, GenGetTilingbyCaseId generates
200	// tiling_data.set_tiling_key(tiling_case_id), so runtime get_tiling_key()
201	// returns the case_id used at codegen time. This allows mapping final_key -> helper.
202	// Trace: GenGetScheduleResult -> group-parallel branch -> GenGroupParallelFirstTiling
203	//   (uses tiling_case_id) -> DoGroupTiling stores group tiling_key via
204	//   group_var.get_tiling_key(). GenGetTilingbyCaseId calls GenerateInputParamsAndTiling
205	//   which emits tiling_data.set_tiling_key(tiling_case_id).
206	struct CacheLineConfig {
207	  CacheLineConfig() = default;
208	  CacheLineConfig(const std::string &name, const Expr &expr, uint32_t size,
209	                  CacheLineDirection cache_line_direction = CacheLineDirection::kUnknown,
210	                  const Expr &solver_expr = Expr())
211	      : node_name(name),
212	        cache_line_expr(expr),
213	        cache_line_size(size),
214	        direction(cache_line_direction),
215	        solver_cache_line_expr(solver_expr) {}
216	
217	  std::string node_name;
218	  // Single transfer bytes (repeats.back() * data_type_size), used by conflict detection
219	  Expr cache_line_expr;
220	  uint32_t cache_line_size;
221	  CacheLineDirection direction{CacheLineDirection::kUnknown};
222	  // Total block bytes (accumulate(input_dims) * data_type_size), used by solver UB constraint.
223	  // Empty when total bytes is a compile-time constant (solver should skip).
224	  Expr solver_cache_line_expr;
225	  std::string ToString() const {
226	    return "node: " + node_name + ", expr: " + Str(cache_line_expr) + ", size: " + std::to_string(cache_line_size);
227	  }
228	  [[nodiscard]] bool IsCacheLineConflictCandidate() const {
229	    return direction == CacheLineDirection::kGmToUb || direction == CacheLineDirection::kUbToGm;
230	  }
231	};
232	
233	struct RuntimeReorderRule {
234	  Expr condition_axis;
235	  Expr compare_axis;
236	  uint32_t condition_threshold{0U};
237	  uint32_t compare_threshold{0U};
238	  std::vector<Expr> preferred_order;
239	};
