279	struct ModelInfo {
280	  uint32_t tiling_case_id;
281	  std::string graph_name;
282	  std::string score_func;
283	  std::string sub_case_tag;                    // Reduce切R，优先切R轴的模板
284	  std::map<int64_t, Expr> workspace_size_map;  // 用于描述每个tensor_id的workspace大小
285	  std::map<HardwareDef, Expr> hardware_cons;   // 用于描述硬件约束
286	  Expr reserved_ub_size{CreateExpr(0)};
287	  std::map<std::string, std::vector<std::pair<Expr, Expr>>>
288	      eq_exprs;  // 用于描述等式约束,切分轴之间的整除约束key值为NO_TAIL
289	  std::map<std::string, std::vector<Expr>> leq_exprs;              // 用于描述不等式约束
290	  std::map<std::string, NodeApiTilingCode> node_name_to_api_code;  // 用于定义高阶API的代码
291	  std::map<std::string, std::pair<std::string, std::string>>
292	      tiling_api_name_to_vars;       // 工具场景高阶API使用, API名,高阶API变量名,高阶API变量类型
293	  std::map<PipeType, Expr> objects;  // 用于描述目标表达式
294	  std::vector<AttAxisPtr> arg_list;  // 用于描述轴以及轴size的信息, owner att axis ptr
295	  std::map<std::string, Expr> container_exprs;
296	  std::map<std::string, Expr> tensor_exprs;
297	  Expr head_cost{CreateExpr(0)};                           // 用于描述多核头开销
298	  ScheduleGroupIdent schedule_group_ident;                 // 标记graph的schedule group信息
299	  ReuseScheduleGroupPtr reuse_schedule_group;              // 标记reuse group信息
300	  ExprExprMap variable_expr_map;                           // 用于记录tensor的表达式
301	  std::map<Expr, std::string, ExprCmp> variable_name_map;  // 用于记录tensor的名称
302	  std::map<Expr, TernaryOp, ExprCmp> ternary_op_map;       // 用于记录三目运算符的名称
303	  std::vector<PerfBreakdownGroup> perf_breakdowns;         // 用于记录性能公式的语义化拆解
304	  uint32_t output_size;
305	  std::vector<af::AscNodePtr> input_nodes;    // 获取输入schedule_results[0].input_nodes
306	  std::vector<af::AscNodePtr> output_nodes;   // 获取输入出schedule_results[0].output_nodes
307	  bool enable_group_parallel{false};          // 使能group并行
308	  std::vector<Expr> sizes{};                  // 图原始Sizes信息
309	  vector<CacheLineConfig> cache_line_config;  // ub->gm/gm->ub节点的cache配置信息
310	  const TilingScheduleConfigTable *tiling_schedule_config_table{nullptr};
311	  TilingScheduleConfig tiling_schedule_config;            // Model 级别的 Tiling 调度配置
312	  bool is_enable_equal_order_tiling{false};               // 使能等order tiling算法
313	  std::vector<RuntimeReorderRule> runtime_reorder_rules;  // 运行时按shape调整单模板内轴优先级
314	};
315	
316	using TilingModelInfo = std::vector<ModelInfo>;
317	using GroupsTilingModelInfo = std::map<size_t, TilingModelInfo>;
318	using TensorIdSet = std::map<size_t, std::map<size_t, std::set<int64_t>>>;
319	// score_funcs: {level, {asc_graph_id, {impl_graph_id, score_func}}
320	using ScoreFuncs = std::map<kModelInfoLevel, std::map<size_t, std::map<size_t, std::string>>>;
321	using EnableGroupParallels = std::map<size_t, std::map<size_t, bool>>;
322	using VarRelations =
323	    std::map<size_t, std::map<size_t, std::map<size_t, std::map<size_t, std::map<std::string, af::Expression>>>>>;
324	// schedule result id->{score_func, group_model_infos}
325	struct ParsedScheduleResult {
326	  size_t asc_graph_id{0UL};
327	  size_t impl_graph_id{0UL};
328	  std::string score_func;
329	  std::map<size_t, std::map<size_t, std::map<std::string, af::Expression>>> var_relations;
330	  GroupsTilingModelInfo groups_tiling_model_info;
331	  bool enable_group_parallel{false};
332	};
333	using FusedParsedScheduleResult = std::map<size_t, std::map<size_t, ParsedScheduleResult>>;
334	}  // namespace att
335	#endif
