118	void EraseVariableByName(ExprExprMap &variable_expr_map, std::map<Expr, std::string, ExprCmp> &variable_name_map,
119	                         const std::string &name) {
120	  for (auto iter = variable_name_map.begin(); iter != variable_name_map.end();) {
121	    if (iter->second == name || Str(iter->first) == name) {
122	      variable_expr_map.erase(iter->first);
123	      iter = variable_name_map.erase(iter);
124	    } else {
125	      ++iter;
126	    }
127	  }
128	  for (auto iter = variable_expr_map.begin(); iter != variable_expr_map.end();) {
129	    if (Str(iter->first) == name) {
130	      iter = variable_expr_map.erase(iter);
131	    } else {
132	      ++iter;
133	    }
134	  }
135	}
