137	void EraseContainerExprs(const std::set<std::string> &container_names, ModelInfo &model_info) {
138	  for (const auto &name : container_names) {
139	    model_info.container_exprs.erase(name);
140	    EraseVariableByName(model_info.variable_expr_map, model_info.variable_name_map, name);
141	  }
142	}
