144	void ApplyCommonUbExprContext(const ascir::UbExprContext &context, ModelInfo &model_info) {
145	  const auto old_ub_container_names = GetUbContainerNames(model_info);
146	  const auto ub_expr_result = ascir::UbExprUtils::BuildUbExpr(context);
147	  if (ub_expr_result.has_ub_expr) {
148	    model_info.hardware_cons[HardwareDef::UB] = ub_expr_result.ub_expr;
149	  } else {
150	    model_info.hardware_cons.erase(HardwareDef::UB);
151	  }
152	  EraseContainerExprs(old_ub_container_names, model_info);
153	  for (const auto &container : context.container_names) {
154	    const auto expr_iter = context.container_expr.find(container.first);
155	    if (expr_iter == context.container_expr.cend()) {
156	      continue;
157	    }
158	    model_info.container_exprs[container.second] = expr_iter->second;
159	    model_info.variable_expr_map[container.first] = expr_iter->second;
160	    model_info.variable_name_map[container.first] = container.second;
161	  }
162	}
