173	af::Status GenerateModelInfo(const af::AscGraph &graph, ModelInfo &model_info, TuningSpacePtr &tuning_space,
174	                             const uint32_t tiling_case_id) {
175	  GELOGI("[DFX]Begin to generate model info for graph %s of tiling case id %u", graph.GetName().c_str(),
176	         tiling_case_id);
177	  DURATION_GUARD(DurationType::DURATION_GEN_MODEL_INFO);
178	  model_info.tiling_case_id = tiling_case_id;
179	  // step1: get tuningspace from compute graph
180	  GE_ASSERT_NOTNULL(tuning_space, "Create tuning space failed.");
181	  att::AscendGraphParser ascend_graph_parser(tuning_space);
182	  GE_ASSERT_SUCCESS(ascend_graph_parser.GraphParser(graph), "Get tuning space failed.");
183	  // step2: get basic expr constraint
184	  att::GenerateTilingExpr tiling_expr(tuning_space);
185	  GE_ASSERT_SUCCESS(tiling_expr.Generate(model_info), "Get basic expr constraint failed.");
186	  GE_ASSERT_SUCCESS(RefreshCommonUbExprContext(graph, model_info), "Refresh common UB expr failed.");
187	  // step3: call passes to get configs
188	  ATTConfig att_config;
189	  std::vector<PassFunc> pass_funcs;
190	  ATTPassMgr::Instance().GetPassList(pass_funcs);
191	  for (auto &pass_func : pass_funcs) {
192	    GE_ASSERT_NOTNULL(pass_func, "Get pass func failed.");
193	    std::map<std::string, std::string> config_str;
194	    GE_ASSERT_TRUE(pass_func(tuning_space, config_str), "Run pass failed.");
195	    for (auto &config : config_str) {
196	      GELOGD("Exe pass: config[%s], value[%s].", config.first.c_str(), config.second.c_str());
197	    }
198	    for (auto &config : config_str) {
199	      att_config.config_names.emplace_back(config.first);
200	      att_config.config_value.insert(config);
201	    }
202	  }
203	  GELOGI("[DFX]End to generate model info for graph %s of tiling case id %u", graph.GetName().c_str(), tiling_case_id);
204	  return af::SUCCESS;
205	}
