331	std::string GetRealPath(const std::string &path) {
332	  if (path.empty() || (path.size() >= kPathMax)) {
333	    GELOGW("Path is size[%zu] exception.", path.size());
334	    return "";
335	  }
336	  std::string root_path = af::RealPath(path.c_str());
337	  GE_ASSERT_TRUE(!root_path.empty(), "Invalid path: %s", path.c_str());
338	  if (!kFileSeperator.empty() && (root_path[root_path.size() - 1U] != kFileSeperator.back())) {
339	    root_path += kFileSeperator;
340	  }
341	
342	  return root_path;
343	}
