468	af::Status GetAllSubImplGraphs(const ascir::FusedScheduledResult &schedule_results,
469	                               std::vector<std::vector<std::vector<std::vector<af::AscGraph>>>> &all_graphs,
470	                               std::map<std::string, std::string> &all_graph_score_funcs) {
471	  bool has_none_graph = true;
472	  for (const auto &asc_graph : schedule_results.node_idx_to_scheduled_results) {
473	    std::vector<std::vector<std::vector<af::AscGraph>>> cur_asc_graphs;
474	    for (const auto &schedule_result : asc_graph) {
475	      std::vector<std::vector<af::AscGraph>> schedule_result_graphs;
476	      for (const auto &schedule_group : schedule_result.schedule_groups) {
477	        schedule_result_graphs.emplace_back(schedule_group.impl_graphs);
478	        all_graph_score_funcs.insert(schedule_group.graph_name_to_score_funcs.begin(),
479	                                     schedule_group.graph_name_to_score_funcs.end());
480	        if (!schedule_group.impl_graphs.empty()) {
481	          has_none_graph = false;
482	        }
483	      }
484	      cur_asc_graphs.emplace_back(schedule_result_graphs);
485	    }
486	    all_graphs.emplace_back(cur_asc_graphs);
487	  }
488	  GE_ASSERT_TRUE(!has_none_graph);
489	  return af::SUCCESS;
490	}
