39	af::Status CopyPerf(const std::string &op_type, uint32_t data_type_size, const std::vector<Expr> &dims,
40	                    const Expr &dim_product, Expr &res) {
41	  GE_ASSERT_TRUE(!dims.empty());
42	  Expr data_size = Mul(dim_product, CreateExpr(data_type_size));
43	  auto it = kBandwidthMap.find(op_type);
44	  GE_ASSERT_TRUE(it != kBandwidthMap.end(), "Op_type[%s] not found in kBandwidthMap", op_type.c_str());
45	  auto cycles = Div(data_size, it->second);
46	  Expr dens = Sub(Mul(dims.back(), kInitA), kInitB);
47	  if (dens == 0) {
48	    dens = CreateExpr(1);
49	  }
50	  auto weight = Div(kSymPowerofEight, dens);
51	  res = Mul(cycles, weight);
52	  return af::SUCCESS;
53	}
