57	af::Status MoveGmtoL1Api([[maybe_unused]] const std::vector<TensorShapeInfo> &input_shapes,
58	                         [[maybe_unused]] const std::vector<TensorShapeInfo> &output_shapes,
59	                         [[maybe_unused]] const NodeInfo &node, PerfOutputInfo &perf_res) {
60	  const auto kNd2NzStartCost = CreateExpr(210U);
61	  GE_ASSERT_TRUE(!input_shapes.empty() && !output_shapes.empty());
62	  auto data_type_size = input_shapes[0].data_type_size;
63	  auto dims = output_shapes[0].dims;
64	  Expr dim_product = accumulate(dims.begin(), dims.end(), CreateExpr(1), [](Expr a, Expr b) { return Mul(a, b); });
65	  GE_ASSERT_TRUE(!dims.empty());
66	  Expr data_size = Mul(dim_product, CreateExpr(data_type_size));
67	  auto it = kBandwidthMap.find(kMoveGmToL1);
68	  GE_ASSERT_TRUE(it != kBandwidthMap.end(), "kMoveGmToL1 not found in kBandwidthMap");
69	  auto cycles = Div(data_size, it->second);
70	  cycles = Add(cycles, kNd2NzStartCost);
71	  Expr dens = Sub(Mul(dims.back(), kInitA), kInitB);
72	  if (dens == 0) {
73	    dens = CreateExpr(1);
74	  }
75	  auto weight = Div(kSymPowerofEight, dens);
76	  perf_res.pipe_res[PipeType::AICORE_MTE2] = Mul(cycles, weight);
77	  return af::SUCCESS;
78	}
