144	                          [[maybe_unused]] const std::vector<TensorShapeInfo> &output_shapes,
145	                          [[maybe_unused]] const NodeInfo &node, PerfOutputInfo &perf_res) {
146	  GE_ASSERT_TRUE(!input_shapes.empty() && !output_shapes.empty());
147	  auto dims = output_shapes[0].dims;
148	  auto input_dims = input_shapes[0].dims;
149	  Expr dim_product =
150	      accumulate(input_dims.begin(), input_dims.end(), CreateExpr(1), [](Expr a, Expr b) { return Mul(a, b); });
151	  Expr res;
152	  GE_ASSERT_SUCCESS(CopyPerf(kMoveL0cToGm, input_shapes[0].data_type_size, dims, dim_product, res));
153	  perf_res.pipe_res[PipeType::AIC_FIXPIPE] = res;
