157	af::Status SoftmaxFlashV2([[maybe_unused]] const std::vector<TensorShapeInfo> &input_shapes,
158	                          [[maybe_unused]] const std::vector<TensorShapeInfo> &output_shapes,
159	                          [[maybe_unused]] const NodeInfo &node, PerfOutputInfo &perf_res) {
160	  (void)output_shapes;
161	  Expr t = CreateExpr(0.89f);
162	  Expr a = CreateExpr(6.14f);
163	  Expr b = CreateExpr(-5.60f);
164	  Expr c = CreateExpr(0.06f);
165	  Expr h = CreateExpr(44.39f);
166	  GE_ASSERT_TRUE(!input_shapes.empty() && !output_shapes.empty());
167	  auto dims = input_shapes[0].dims;
168	  GE_ASSERT_TRUE(!dims.empty());
169	  Expr dim_product = accumulate(dims.begin(), dims.end(), CreateExpr(1), [](Expr a, Expr b) { return Mul(a, b); });
170	  auto cycles = Div(dim_product, t);
171	  auto weight = Add(Div(a, Add(dims.back(), b)), c);
172	  cycles = Mul(cycles, weight);
173	  perf_res.pipe_res[PipeType::AIV_VEC] = Add(cycles, h);
174	  return af::SUCCESS;
175	}
176	
177	/*
178	Loadapi(DataCopy from GM to UB)的性能公式：
179	  1. 单次MTE2 = S(数据量Byte)/T + h(指令头开销)，针对非连续搬运场景会增加stride建模值(k*(stride%(256)*block_count))
180	  2. 总MTE2 = 单次MTE2 * 调用次数 + H(pipe启动头开销)
181	  3. H = 15.8854 * blockdim + 882.0878 (datasize < 25000B)
182	     H = 32.7221 * blockdim + 1575.0306 (datasize >= 25000B)
183	  4. h = 27.01
184	  5. T = 7.9052 + 7.3100/blockdim (datasize < 25000B)
185	     T = 9.9074 + 15.8960/blockdim (datasize >= 25000B)
186	     (单核的峰值带宽，核数越多，带宽抢占越严重，直到收敛到稳定值约为8.47)
187	  6. mte2 = S/T + h
188	  7. overall_mte2 = mte2 * mte2_count + H
189	  8. 外抛for循环：最外侧两个维度丢到循环次数里面去
190	*/
191	
192	// DMA节点性能计算辅助函数（消除LoadApi和StoreApi重复代码）
193	af::Status InitDmaNodeAndGetPerf(const af::AscNodePtr &node_ptr, const std::string &node_name,
194	                                 TensorShapeInfo &merged_shapes, PerfOutputInfo &perf_res) {
195	  GE_ASSERT_SUCCESS(MergeTensorContinuousDims(node_ptr, GetNodeOutTensorName(node_ptr, 0), merged_shapes));
196	
197	  NodeDetail dma_info;
198	  dma_info.name = node_ptr != nullptr ? node_ptr->GetName() : node_name;
199	  dma_info.optype = node_ptr->GetType();
200	  dma_info.input_dtype = {merged_shapes.data_type};
201	  dma_info.output_dtype = {merged_shapes.data_type};
202	
203	  GE_ASSERT_SUCCESS(SetDims(merged_shapes, dma_info));
204	  GE_ASSERT_SUCCESS(GetDmaPerf(merged_shapes, dma_info, perf_res, kMaxDmaLen, true));
205	  return af::SUCCESS;
206	}
207	
208	af::Status LoadApi([[maybe_unused]] const std::vector<TensorShapeInfo> &input_shapes,
209	                   [[maybe_unused]] const std::vector<TensorShapeInfo> &output_shapes,
210	                   [[maybe_unused]] const NodeInfo &node, PerfOutputInfo &perf_res) {
211	  auto const &node_ptr = node.node_ptr;
212	  GE_ASSERT_TRUE(!input_shapes.empty() && !output_shapes.empty());
213	
214	  auto merged_shapes = output_shapes[0];
215	  return InitDmaNodeAndGetPerf(node_ptr, "LoadNode", merged_shapes, perf_res);
216	}
217	
218	/*
219	StoreApi(DataCopy from UB to GM)的性能公式：
220	  1. 单次MTE3 = S(数据量Byte)/T + h(指令头开销)，针对非连续搬运场景会增加stride建模值(k*(stride%(256)*block_count))
221	  2. 总MTE3 = 单次MTE3 * 调用次数 + H(pipe启动头开销)
222	  3. H = 497.36
223	  4. h = 12.09
224	  5. T = 9.96 + 3.79/blockdim(单核的峰值带宽，核数越多，带宽抢占越严重，直到收敛到稳定值约为9.96)
225	  6. mte3 = S/T + h
226	  7. overall_mte3 = mte3 * mte3_count + H
227	  8. 外抛for循环：最外侧两个维度丢到循环次数里面去
228	*/
229	af::Status StoreApi([[maybe_unused]] const std::vector<TensorShapeInfo> &input_shapes,
230	                    [[maybe_unused]] const std::vector<TensorShapeInfo> &output_shapes,
231	                    [[maybe_unused]] const NodeInfo &node, PerfOutputInfo &perf_res) {
232	  auto const &node_ptr = node.node_ptr;
233	  GE_ASSERT_TRUE(!input_shapes.empty() && !output_shapes.empty());
234	
235	  auto merged_shapes = output_shapes[0];
236	  return InitDmaNodeAndGetPerf(node_ptr, "StoreNode", merged_shapes, perf_res);
237	}
238	
239	af::Status AbsApi([[maybe_unused]] const std::vector<TensorShapeInfo> &input_shapes,
240	                  [[maybe_unused]] const std::vector<TensorShapeInfo> &output_shapes,
241	                  [[maybe_unused]] const NodeInfo &node, PerfOutputInfo &perf_res) {
242	  NodeDetail node_info;
243	  GE_ASSERT_SUCCESS(SetNodeDetail(input_shapes, output_shapes, node_info));
244	  GE_ASSERT_SUCCESS(ascendcperf::AbsPerf(node_info, perf_res));
245	  return af::SUCCESS;
246	}
247	
248	af::Status AddApi([[maybe_unused]] const std::vector<TensorShapeInfo> &input_shapes,
249	                  [[maybe_unused]] const std::vector<TensorShapeInfo> &output_shapes,
250	                  [[maybe_unused]] const NodeInfo &node, PerfOutputInfo &perf_res) {
251	  NodeDetail node_info;
252	  GE_ASSERT_SUCCESS(SetNodeDetail(input_shapes, output_shapes, node_info));
253	  GE_ASSERT_SUCCESS(ascendcperf::AddPerf(node_info, perf_res), "Add perf failed, node name: %s, type: %s",
254	                    node_info.name.c_str(), node_info.optype.c_str());
255	  return af::SUCCESS;
256	}
257	
258	af::Status CastApi([[maybe_unused]] const std::vector<TensorShapeInfo> &input_shapes,
259	                   [[maybe_unused]] const std::vector<TensorShapeInfo> &output_shapes,
260	                   [[maybe_unused]] const NodeInfo &node, PerfOutputInfo &perf_res) {
261	  auto const &node_ptr = node.node_ptr;
262	  GE_ASSERT_TRUE(!input_shapes.empty() && !output_shapes.empty());
263	  NodeDetail node_info;
264	  Expr outer_repeat;
265	  vector<Expr> used_dims;
266	  auto merged_output_shapes = output_shapes[0];
267	  GE_ASSERT_SUCCESS(MergeTensorContinuousDims(node_ptr, GetNodeOutTensorName(node_ptr, 0), merged_output_shapes));
268	  GE_ASSERT_SUCCESS(GetOuterParams(merged_output_shapes.dims, outer_repeat, used_dims));
269	  GE_ASSERT_SUCCESS(SetNodeDetail(input_shapes, output_shapes, node_info));
270	  GE_ASSERT_SUCCESS(SetDims(used_dims, node_info));
271	  GE_ASSERT_SUCCESS(ascendcperf::CastPerf(node_info, perf_res), "Cast perf failed, node name: %s, type: %s",
272	                    node_info.name.c_str(), node_info.optype.c_str());
273	  perf_res.pipe_res[PipeType::AIV_VEC] = outer_repeat * GetPipeCost(perf_res, PipeType::AIV_VEC);
274	  return af::SUCCESS;
275	}
276	
277	af::Status CopyApi([[maybe_unused]] const std::vector<TensorShapeInfo> &input_shapes,
278	                   [[maybe_unused]] const std::vector<TensorShapeInfo> &output_shapes,
279	                   [[maybe_unused]] const NodeInfo &node, PerfOutputInfo &perf_res) {
280	  NodeDetail node_info;
281	  GE_ASSERT_SUCCESS(SetNodeDetail(input_shapes, output_shapes, node_info));
282	  GE_ASSERT_SUCCESS(ascendcperf::CopyPerf(node_info, perf_res));
283	  return af::SUCCESS;
284	}
285	
286	af::Status DivApi([[maybe_unused]] const std::vector<TensorShapeInfo> &input_shapes,
287	                  [[maybe_unused]] const std::vector<TensorShapeInfo> &output_shapes,
288	                  [[maybe_unused]] const NodeInfo &node, PerfOutputInfo &perf_res) {
289	  NodeDetail node_info;
290	  GE_ASSERT_SUCCESS(SetNodeDetail(input_shapes, output_shapes, node_info));
291	  GE_ASSERT_SUCCESS(ascendcperf::DivPerf(node_info, perf_res), "Div perf failed, node name: %s, type: %s",
292	                    node_info.name.c_str(), node_info.optype.c_str());
293	  return af::SUCCESS;
294	}
295	
296	af::Status ErfApi([[maybe_unused]] const std::vector<TensorShapeInfo> &input_shapes,
297	                  [[maybe_unused]] const std::vector<TensorShapeInfo> &output_shapes,
298	                  [[maybe_unused]] const NodeInfo &node, PerfOutputInfo &perf_res) {
