416	af::Status BroadcastOuter(const std::string &data_type, const std::vector<Expr> &input_dims,
417	                          const std::vector<Expr> &output_dims, PerfOutputInfo &perf_res) {
418	  (void)input_dims;
419	  auto it = kRptEleMap.find(data_type);
420	  GE_ASSERT_TRUE(it != kRptEleMap.end(), "Data type [%s] unsatisfied.", data_type.c_str());
421	  Expr ele_per_rpt = it->second;
422	  Expr dst_m = output_dims[0];
423	  Expr max_rpt_cnt = dst_m / kMaxRepeatTime;
424	  Expr tail_rpt_times = dst_m - max_rpt_cnt * kMaxRepeatTime;
425	  Expr tail_pad = af::sym::Ceiling(tail_rpt_times / (tail_rpt_times + CreateExpr(1)));
426	  PerfOutputInfo rpt_perf;
427	  PerfOutputInfo tail_perf;
428	  NodeDetail copy_node1 = GenNodeDetail(data_type, data_type, {kMaxRepeatTime * ele_per_rpt});
429	  NodeDetail copy_node2 = GenNodeDetail(data_type, data_type, {tail_rpt_times * ele_per_rpt});
430	  GE_ASSERT_SUCCESS(ascendcperf::CopyPerf(copy_node1, rpt_perf), "Gen CopyApi perf failed, node name: %s, type: %s",
431	                    copy_node1.name.c_str(), copy_node1.optype.c_str());
432	  GE_ASSERT_SUCCESS(ascendcperf::CopyPerf(copy_node2, tail_perf), "Gen CopyApi perf failed, node name: %s, type: %s",
433	                    copy_node2.name.c_str(), copy_node2.optype.c_str());
434	  perf_res.pipe_res[PipeType::AIV_VEC] =
435	      max_rpt_cnt * GetPipeCost(rpt_perf, PipeType::AIV_VEC) + tail_pad * GetPipeCost(tail_perf, PipeType::AIV_VEC);
436	  return af::SUCCESS;
437	}
