439	af::Status BrcbToOneBlockPerf(const std::string &data_type, Expr first_dim, Expr last_dim, PerfOutputInfo &perf_res) {
440	  (void)last_dim;
441	  auto iter1 = kBlkEleMap.find(data_type);
442	  auto iter2 = kBrcbRepeatMap.find(data_type);
443	  GE_ASSERT_TRUE((iter1 != kBlkEleMap.end() && iter2 != kBrcbRepeatMap.end()), "Data type [%s] unsatisfied.",
444	                 data_type.c_str());
445	  PerfOutputInfo brcb_repeat_perf;
446	  PerfOutputInfo brcb_tail_perf;
447	  const auto kBrcbSize = CreateExpr(8U);
448	  Expr brcb_rpt_times = af::sym::Ceiling(first_dim / kBrcbSize) * kBrcbSize;
449	  Expr ele_per_order = iter1->second;
450	  Expr brcb_max_rpt_times = iter2->second;
451	  Expr loop_cnt = brcb_rpt_times / brcb_max_rpt_times;
452	  Expr tail_rpt = brcb_rpt_times - loop_cnt * brcb_max_rpt_times;
453	  Expr brcb_pad = af::sym::Ceiling(tail_rpt / (tail_rpt + CreateExpr(1)));
454	  NodeDetail brcb_node1 = GenNodeDetail(data_type, data_type, {brcb_max_rpt_times * ele_per_order});
455	  NodeDetail brcb_node2 = GenNodeDetail(data_type, data_type, {tail_rpt * ele_per_order});
456	  GE_ASSERT_SUCCESS(ascendcperf::BrcbPerf(brcb_node1, brcb_repeat_perf),
457	                    "Gen BrcbApi perf failed, node name: %s, type: %s", brcb_node1.name.c_str(),
458	                    brcb_node1.optype.c_str());
459	  GE_ASSERT_SUCCESS(ascendcperf::BrcbPerf(brcb_node2, brcb_tail_perf),
460	                    "Gen BrcbApi perf failed, node name: %s, type: %s", brcb_node2.name.c_str(),
461	                    brcb_node2.optype.c_str());
462	  perf_res.pipe_res[PipeType::AIV_VEC] = loop_cnt * GetPipeCost(brcb_repeat_perf, PipeType::AIV_VEC) +
463	                                         brcb_pad * GetPipeCost(brcb_tail_perf, PipeType::AIV_VEC);
464	  return af::SUCCESS;
465	}
