486	  perf_res.pipe_res[PipeType::AIV_VEC] = GetPipeCost(brcb_perf, PipeType::AIV_VEC) +
487	                                         copy_cnt * GetPipeCost(copy_repeat_perf, PipeType::AIV_VEC) +
