492	af::Status TwoDimBroadcastLastDim(const std::string &data_type, const std::vector<Expr> &input_dims,
493	                                  const std::vector<Expr> &output_dims, PerfOutputInfo &perf_res, bool with_stride) {
494	  (void)input_dims;
495	  Expr one_block_ele_num;
496	  GE_ASSERT_SUCCESS(GetBlkEleNum(data_type, one_block_ele_num), "Data type [%s] unsatisfied.", data_type.c_str());
497	  PerfOutputInfo repeat_perf;
498	  PerfOutputInfo tail_perf;
499	  const auto &first_dim = output_dims[0];
500	  const auto &last_dim = output_dims[1];
501	  Expr stride = with_stride ? one_block_ele_num : CreateExpr(0);
502	  Expr min_tmp_buffer_size = one_block_ele_num * one_block_ele_num + stride;
503	  Expr one_repeat_size = kTempBufSize / min_tmp_buffer_size * one_block_ele_num;
504	  Expr range_m = first_dim / one_repeat_size;
505	  Expr tail_m = first_dim - one_repeat_size * range_m;
506	  Expr pad_m = af::sym::Ceiling(tail_m / (tail_m + CreateExpr(1)));
507	  GE_ASSERT_SUCCESS(TwoDimBroadCastLastDimAlignPerf(data_type, one_repeat_size, last_dim, repeat_perf),
508	                    "Gen TwoDimBroadCastLastDimAlignPerf perf Failed.");
509	  GE_ASSERT_SUCCESS(TwoDimBroadCastLastDimAlignPerf(data_type, tail_m, last_dim, tail_perf),
510	                    "Gen TwoDimBroadCastLastDimAlignPerf perf Failed.");
511	  perf_res.pipe_res[PipeType::AIV_VEC] =
512	      range_m * GetPipeCost(repeat_perf, PipeType::AIV_VEC) + pad_m * GetPipeCost(tail_perf, PipeType::AIV_VEC);
513	  return af::SUCCESS;
514	}
