516	af::Status BroadcastMiddle(const std::string &data_type, const std::vector<Expr> &input_dims,
517	                           const std::vector<Expr> &output_dims, PerfOutputInfo &perf_res) {
518	  (void)input_dims;
519	  auto iter1 = kBlkEleMap.find(data_type);
520	  auto iter2 = kRptEleMap.find(data_type);
521	  GE_ASSERT_TRUE((iter1 != kBlkEleMap.end() && iter2 != kRptEleMap.end()), "Data type [%s] unsatisfied.",
522	                 data_type.c_str());
523	  PerfOutputInfo duplicate_perf;
524	  PerfOutputInfo or_perf;
525	  Expr dst_m = output_dims[0];
526	  Expr dst_k = output_dims[1];
527	  Expr dst_z = output_dims[2];
528	  Expr one_blk_num = iter1->second;
529	  Expr one_rpt_num = iter2->second;
530	  Expr outer_dim_max_loop = kMaxRepeatTime * one_blk_num;
531	  Expr loop_cnt = dst_k / kSymEight;
532	  Expr rpt = dst_z / one_blk_num;
533	  Expr loop_tail = dst_k - loop_cnt * kSymEight;
534	  Expr loop_pad = af::sym::Ceiling(loop_tail / (loop_tail + CreateExpr(1)));
535	  NodeDetail duplicate_node = GenNodeDetail("uint16", "uint16", {CreateExpr(16)});
536	  NodeDetail or_node = GenNodeDetail("uint16", "uint16", {rpt * one_rpt_num});
537	  GE_ASSERT_SUCCESS(ascendcperf::DuplicatePerf(duplicate_node, duplicate_perf),
538	                    "Gen Duplicate perf failed, node name: %s, type: %s", duplicate_node.name.c_str(),
539	                    duplicate_node.optype.c_str());
540	  GE_ASSERT_SUCCESS(ascendcperf::OrPerf(or_node, or_perf), "Gen Or perf failed, node name: %s, type: %s",
541	                    or_node.name.c_str(), or_node.optype.c_str());
542	  perf_res.pipe_res[PipeType::AIV_VEC] = dst_m * (GetPipeCost(duplicate_perf, PipeType::AIV_VEC) +
543	                                                  (loop_cnt + loop_pad) * GetPipeCost(or_perf, PipeType::AIV_VEC));
544	  return af::SUCCESS;
545	}
