586	af::Status BroadcastFourDim(const std::string &data_type, const std::vector<Expr> &input_dims,
587	                            const std::vector<Expr> &output_dims, PerfOutputInfo &perf_res) {
588	  std::vector<Expr> cur_input_dims;
589	  std::vector<Expr> cur_output_dims;
590	  PerfOutputInfo broadcast_perf1;
591	  PerfOutputInfo broadcast_perf2;
592	  if (input_dims[kNumZero] == 1U && input_dims[kNumTwo] == 1U && input_dims[kNumOne] == output_dims[kNumOne] &&
593	      input_dims[kNumThree] == output_dims[kNumThree]) {
594	    cur_input_dims = {input_dims[kNumOne], input_dims[kNumTwo], input_dims[kNumThree]};
