598	    cur_input_dims = {input_dims[kNumZero], output_dims[kNumOne] * output_dims[kNumTwo] * output_dims[kNumThree]};
599	    cur_output_dims = {output_dims[kNumZero], output_dims[kNumOne] * output_dims[kNumTwo] * output_dims[kNumThree]};
600	    GE_ASSERT_SUCCESS(BroadcastTwoDim(data_type, cur_input_dims, cur_output_dims, broadcast_perf2),
601	                      "Gen Broadcast perf Failed.");
602	    perf_res.pipe_res[PipeType::AIV_VEC] =
603	        GetPipeCost(broadcast_perf1, PipeType::AIV_VEC) + GetPipeCost(broadcast_perf2, PipeType::AIV_VEC);
604	  } else if (input_dims[kNumZero] == output_dims[kNumZero] && input_dims[kNumOne] == 1U &&
605	             input_dims[kNumTwo] == output_dims[kNumTwo] && input_dims[kNumThree] == 1U) {
606	    cur_input_dims = {input_dims[kNumZero] * input_dims[kNumOne] * input_dims[kNumTwo], input_dims[kNumThree]};
607	    cur_output_dims = {input_dims[kNumZero] * input_dims[kNumOne] * input_dims[kNumTwo], output_dims[kNumThree]};
608	    GE_ASSERT_SUCCESS(BroadcastTwoDim(data_type, cur_input_dims, cur_output_dims, broadcast_perf1),
609	                      "Gen Broadcast perf Failed.");
610	    cur_input_dims = {input_dims[kNumZero], input_dims[kNumOne], input_dims[kNumTwo] * output_dims[kNumThree]};
611	    cur_output_dims = {output_dims[kNumZero], output_dims[kNumOne], output_dims[kNumTwo] * output_dims[kNumThree]};
612	    GE_ASSERT_SUCCESS(BroadcastThreeDim(data_type, cur_input_dims, cur_output_dims, broadcast_perf2),
613	                      "Gen Broadcast perf Failed.");
614	    perf_res.pipe_res[PipeType::AIV_VEC] =
615	        GetPipeCost(broadcast_perf1, PipeType::AIV_VEC) + GetPipeCost(broadcast_perf2, PipeType::AIV_VEC);
616	  }
617	  return af::SUCCESS;
618	}
