620	af::Status ExpandBroadCastDims(std::vector<Expr> &input_dims, const std::vector<Expr> &output_dims) {
621	  size_t offset = 0;
622	  Expr insert_dim;
623	  std::string expand_log;
624	  std::vector<bool> valid_dims(output_dims.size(), false);
625	  for (size_t i = 0; i < input_dims.size(); ++i) {
626	    if (input_dims[i] != output_dims[i + offset]) {
627	      if (offset == 0 && input_dims[i] == output_dims[i + 1]) {
628	        valid_dims[i] = true;
629	        ++offset;
630	      } else {
631	        GELOGW("Two Dim broadcast.");
632	      }
633	    }
634	  }
635	  input_dims.clear();
636	  for (size_t i = 0; i < output_dims.size(); ++i) {
637	    if (i > 0) {
638	      expand_log += ", ";
639	    }
640	    insert_dim = valid_dims[i] ? af::sym::kSymbolOne : output_dims[i];
641	    input_dims.emplace_back(insert_dim);
642	    expand_log += Str(insert_dim);
643	  }
644	  GELOGD("Expand input shape: {%s}", expand_log.c_str());
645	  return af::SUCCESS;
646	}
