648	/*
649	BroadCast合轴处理：
650	(1, A, B) -> (1, A * B)
651	(A, 1, B, C) -> (A, 1, B * C)
652	*/
653	af::Status MergeAxis(std::vector<Expr> &input_dims, std::vector<Expr> &output_dims) {
654	  Expr tmp = af::sym::kSymbolOne;
655	  bool status = true;
656	  for (const auto &expr : input_dims) {
657	    if (expr == 1U) {
658	      status = false;
659	      break;
660	    }
661	  }
662	  if (status) {
663	    return af::SUCCESS;
664	  }
665	  std::vector<Expr> tmp_input_dims = input_dims;
666	  std::vector<Expr> tmp_output_dims = output_dims;
667	  input_dims.clear();
668	  output_dims.clear();
669	  for (size_t i = 0; i < tmp_input_dims.size(); ++i) {
670	    if (tmp_input_dims[i] == 1 && tmp_output_dims[i] != 1) {
671	      if (tmp != 1) {
672	        input_dims.emplace_back(tmp);
673	        output_dims.emplace_back(tmp);
674	      }
675	      tmp = af::sym::kSymbolOne;
676	      input_dims.emplace_back(tmp_input_dims[i]);
677	      output_dims.emplace_back(tmp_output_dims[i]);
678	    } else {
679	      if (tmp_input_dims[i] != tmp_output_dims[i]) {
680	        GELOGW("Invalid merge.");
681	      }
682	      tmp = Mul(tmp, tmp_input_dims[i]);
683	    }
684	  }
685	  if (tmp != 1) {
686	    input_dims.emplace_back(tmp);
687	    output_dims.emplace_back(tmp);
688	  }
689	  return af::SUCCESS;
690	}
