692	/*
693	Broadcastapi的性能公式：
694	1) input_shapes[0].dims[0] = 1 && input_shapes[0].dims[1] = output_shapes[0].dims[1]:
695	  (1, B) -> (A, B)
696	  (1, B, C) -> (A, B, C)
697	  调用BroadcastFirstDim函数
698	  A * CopyApi(B * C)
699	2) input_shapes[0].dims[0] = output_shapes[0].dims[0] && input_shapes[0].dims[1] = 1:
700	  2.1) input_shapes[0].dims.size() == 2
701	    (A, 1) -> (A, B)
702	    调用TwoDimBroadCastLastDim<2,1>的函数
703	    首先执行tempbuf / (A / (32B * 32B) * 32B)次Align220函数：
704	      执行Align((A / (32B * 32B) * 32B), 8) / 255次Brcb，处理数据量为254或25
705	      尾块执行一次Brcb
706	      执行(A / (32B * 32B) * 32B)/255次Copy，处理数据为255 * B
707	      首轴的尾块再执行一次Copy
708	    再根据tempbuf / (A / (32B * 32B) * 32B)的尾块执行一次Align220
709	  2.2) input_shapes[0].dims.size() != 2
710	    (A, 1, C) -> (A, B, C)
711	      Duplicate + Or
712	3) input_shapes[0].dims.size() == 2 && output_shapes[0].dims.size() == 2 &&
713	  input_shapes[0].dims[0] = 1 && input_shapes[0].dims[1] = 1
714	    (1, 1) -> (A, B)
715	    DuplicateApi(A * B)
716	4) input_dims[0] == 1U && input_dims[2] == 1U && input_dims[1] == output_dims[1] && input_dims[3] == output_dims[3]
717	  (1, B, 1, B) -> (A, B, A, B)
718	  Broadcast (B,1,B)->(B,A,B)
719	  Broadcast (1,BAB)->(A,BAB)
720	*/
721	af::Status BroadcastApi([[maybe_unused]] const std::vector<TensorShapeInfo> &input_shapes,
722	                        [[maybe_unused]] const std::vector<TensorShapeInfo> &output_shapes,
723	                        [[maybe_unused]] const NodeInfo &node, PerfOutputInfo &perf_res) {
724	  auto const &node_ptr = node.node_ptr;
725	  GE_ASSERT_TRUE(!output_shapes.empty() && !input_shapes.empty());
726	  auto input_dims = input_shapes[0].dims;
727	  auto output_dims = output_shapes[0].dims;
728	  GE_ASSERT_TRUE(!input_dims.empty() && !output_dims.empty());
729	  if (input_dims.size() != output_dims.size()) {
730	    GE_ASSERT_SUCCESS(ExpandBroadCastDims(input_dims, output_dims), "Expand failed, input size {%s}, output size {%s}.",
731	                      input_shapes[0].GetDimExpr().c_str(), output_shapes[0].GetDimExpr().c_str());
732	  }
733	  GE_ASSERT_TRUE(input_dims.size() == output_dims.size(), "input_dims.size() != output_dims.size()");
734	  GE_ASSERT_SUCCESS(MergeAxis(input_dims, output_dims), "MergeAxis Failed!");
735	  if (input_dims.size() == 2U) {
736	    GE_ASSERT_SUCCESS(BroadcastTwoDim(input_shapes[0].data_type, input_dims, output_dims, perf_res),
737	                      "Gen BroadcastTwoDim perf Failed, input size {%s}, output size {%s}.",
738	                      input_shapes[0].GetDimExpr().c_str(), output_shapes[0].GetDimExpr().c_str());
739	  } else if (input_dims.size() == 3U) {
740	    GE_ASSERT_SUCCESS(BroadcastThreeDim(input_shapes[0].data_type, input_dims, output_dims, perf_res),
741	                      "Gen BroadcastThreeDim perf Failed, input size {%s}, output size {%s}.",
742	                      input_shapes[0].GetDimExpr().c_str(), output_shapes[0].GetDimExpr().c_str());
743	  } else if (input_dims.size() == 4U) {
744	    GE_ASSERT_SUCCESS(BroadcastFourDim(input_shapes[0].data_type, input_dims, output_dims, perf_res),
745	                      "Gen BroadcastThreeDim perf Failed, input size {%s}, output size {%s}.",
746	                      input_shapes[0].GetDimExpr().c_str(), output_shapes[0].GetDimExpr().c_str());
747	  } else if (input_dims.size() == 1U) {
748	    GE_ASSERT_SUCCESS(ascendcperf::DuplicatePerf(
749	                          GenNodeDetail(input_shapes[0].data_type, output_shapes[0].data_type, output_dims), perf_res),
750	                      "Gen DuplicateApi perf failed, node name: %s, type: %s", node_ptr->GetNamePtr(),
751	                      node_ptr->GetTypePtr());
752	  } else {
753	    GELOGW("input_dims.size[%zu] unsupported, input size {%s}, output size {%s}.", input_dims.size(),
754	           input_shapes[0].GetDimExpr().c_str(), output_shapes[0].GetDimExpr().c_str());
755	    perf_res.pipe_res[PipeType::AIV_VEC] = af::sym::kSymbolZero;
756	  }
757	  return af::SUCCESS;
758	}
