760	af::Status LogicalCommonApi([[maybe_unused]] const std::vector<TensorShapeInfo> &input_shapes,
761	                            [[maybe_unused]] const std::vector<TensorShapeInfo> &output_shapes,
762	                            [[maybe_unused]] const NodeInfo &node, PerfOutputInfo &perf_res,
763	                            const std::function<af::Status(const NodeDetail &, PerfOutputInfo &)> &calc_func_perf) {
764	  auto const &node_ptr = node.node_ptr;
765	  GE_ASSERT_TRUE(!input_shapes.empty());
766	  Expr data_size;
767	  Expr max_repeat_size = af::sym::Min(kTempBufSize / kSymPowerofEight, kMaxRepeatTime) * kSymPowerofSeven;
768	  GE_ASSERT_SUCCESS(ascendcperf::GetDatasize(output_shapes[0], data_size));
769	  PerfOutputInfo cast_perf1;
770	  PerfOutputInfo cast_perf2;
771	  PerfOutputInfo cast_perf3;
772	  PerfOutputInfo cast_perf4;
773	  PerfOutputInfo mul_perf1;
774	  PerfOutputInfo mul_perf2;
775	  Expr cycle_num = data_size / max_repeat_size;
776	  GE_ASSERT_SUCCESS(
777	      ascendcperf::CastPerf(GenNodeDetail(output_shapes[0].data_type, "float16", {max_repeat_size}), cast_perf1),
778	      "CastPerf failed, node=[%s,%s]", node_ptr->GetNamePtr(), node_ptr->GetTypePtr());
779	  GE_ASSERT_SUCCESS(ascendcperf::CastPerf(GenNodeDetail("float16", "uint8", {max_repeat_size}), cast_perf2),
780	                    "CastPerf failed, node=[%s,%s]", node_ptr->GetNamePtr(), node_ptr->GetTypePtr());
781	  GE_ASSERT_SUCCESS(
782	      ascendcperf::CastPerf(
783	          GenNodeDetail(output_shapes[0].data_type, "float16", {data_size - cycle_num * max_repeat_size}), cast_perf3),
784	      "Gen node detail failed, node=[%s,%s]", node_ptr->GetNamePtr(), node_ptr->GetTypePtr());
785	  GE_ASSERT_SUCCESS(
786	      ascendcperf::CastPerf(GenNodeDetail("float16", "uint8", {data_size - cycle_num * max_repeat_size}), cast_perf4),
787	      "CastPerf failed, node=[%s,%s]", node_ptr->GetNamePtr(), node_ptr->GetTypePtr());
788	  GE_ASSERT_SUCCESS(calc_func_perf(GenNodeDetail("float16", "float16", {max_repeat_size}), mul_perf1),
789	                    "Calc func perf failed, node=[%s,%s]", node_ptr->GetNamePtr(), node_ptr->GetTypePtr());
790	  GE_ASSERT_SUCCESS(
791	      calc_func_perf(GenNodeDetail("float16", "float16", {data_size - cycle_num * max_repeat_size}), mul_perf2),
792	      "Calc func perf failed, node=[%s,%s]", node_ptr->GetNamePtr(), node_ptr->GetTypePtr());
793	  perf_res.pipe_res[PipeType::AIV_VEC] =
794	      kSymTwo * cycle_num * GetPipeCost(cast_perf1, PipeType::AIV_VEC) +
795	      cycle_num * GetPipeCost(mul_perf1, PipeType::AIV_VEC) + cycle_num * GetPipeCost(cast_perf2, PipeType::AIV_VEC) +
796	      kSymTwo * GetPipeCost(cast_perf3, PipeType::AIV_VEC) + GetPipeCost(mul_perf2, PipeType::AIV_VEC) +
797	      GetPipeCost(cast_perf4, PipeType::AIV_VEC);
798	  return af::SUCCESS;
799	}
