826	*/
827	af::Status LogicalNotApi([[maybe_unused]] const std::vector<TensorShapeInfo> &input_shapes,
828	                         [[maybe_unused]] const std::vector<TensorShapeInfo> &output_shapes,
829	                         [[maybe_unused]] const NodeInfo &node, PerfOutputInfo &perf_res) {
830	  auto const &node_ptr = node.node_ptr;
831	  GE_ASSERT_TRUE(!input_shapes.empty());
832	  Expr data_size;
833	  Expr max_repeat_size = af::sym::Min((CreateExpr(8160)) / kSymPowerofEight, kMaxRepeatTime) * kSymPowerofSeven;
834	  GE_ASSERT_SUCCESS(ascendcperf::GetDatasize(output_shapes[0], data_size));
835	  GE_ASSERT_TRUE(output_shapes[0].data_type != "float32");
836	  PerfOutputInfo duplicate_perf;
837	  PerfOutputInfo abs_perf1;
838	  PerfOutputInfo min_perf1;
839	  PerfOutputInfo sub_perf1;
