847	  GE_ASSERT_SUCCESS(ascendcperf::SubPerf(GenNodeDetail("float16", "float16", {max_repeat_size}), sub_perf1));
848	  GE_ASSERT_SUCCESS(
849	      ascendcperf::AbsPerf(GenNodeDetail("float16", "float16", {data_size - cycle_num * max_repeat_size}), abs_perf2),
850	      "Abs perf failed, node=[%s,%s]", node_ptr->GetNamePtr(), node_ptr->GetTypePtr());
