852	      ascendcperf::MinPerf(GenNodeDetail("float16", "float16", {data_size - cycle_num * max_repeat_size}), min_perf2),
853	      "Min perf failed, node=[%s,%s]", node_ptr->GetNamePtr(), node_ptr->GetTypePtr());
854	  GE_ASSERT_SUCCESS(
855	      ascendcperf::SubPerf(GenNodeDetail("float16", "float16", {data_size - cycle_num * max_repeat_size}), sub_perf2),
856	      "Sub perf failed, node=[%s,%s]", node_ptr->GetNamePtr(), node_ptr->GetTypePtr());
857	  perf_res.pipe_res[PipeType::AIV_VEC] =
858	      GetPipeCost(duplicate_perf, PipeType::AIV_VEC) + kSymTwo * cycle_num * GetPipeCost(abs_perf1, PipeType::AIV_VEC) +
859	      cycle_num * GetPipeCost(min_perf1, PipeType::AIV_VEC) + cycle_num * GetPipeCost(sub_perf1, PipeType::AIV_VEC) +
860	      kSymTwo * GetPipeCost(abs_perf2, PipeType::AIV_VEC) + GetPipeCost(min_perf2, PipeType::AIV_VEC) +
861	      GetPipeCost(sub_perf2, PipeType::AIV_VEC);
862	  return af::SUCCESS;
863	}
