865	/*
866	ReduceMaxapi的性能公式：
867	  比较复杂，目前先实现AR形式且isReuseSource=false的场景
868	  建模时根据尾轴>32B且<256B的分支建模
869	*/
870	af::Status ReduceMaxPerf([[maybe_unused]] const std::vector<TensorShapeInfo> &input_shapes, PerfOutputInfo &perf_res) {
871	  std::string data_type = input_shapes[0].data_type;
872	  auto dims = input_shapes[0].dims;
873	  GE_ASSERT_TRUE(dims.size() == 2U);
874	  auto it = kBlkEleMap.find(input_shapes[0].data_type);
875	  GE_ASSERT_TRUE(it != kBlkEleMap.end());
876	  PerfOutputInfo adds_perf;
877	  PerfOutputInfo max_perf1;
878	  PerfOutputInfo max_perf2;
879	  PerfOutputInfo max_perf3;
880	  PerfOutputInfo blockreducemax_perf;
881	  const auto &first = dims[0];
882	  const auto &last = dims[1];
883	  Expr first_repeat = first / kMaxRepeatTime;
884	  Expr repeat_tail = first - first_repeat * kMaxRepeatTime;
885	  Expr ele_per_blk = it->second;
886	  Expr blk_count = last / ele_per_blk;
887	  Expr blk_tail = last - blk_count * ele_per_blk;
888	  Expr blk_pad = af::sym::Ceiling(blk_tail / (blk_tail + CreateExpr(1)));
889	  GE_ASSERT_SUCCESS(ascendcperf::AddsPerf(GenNodeDetail(data_type, data_type, {first * ele_per_blk}), adds_perf));
890	  GE_ASSERT_SUCCESS(ascendcperf::MaxPerf(GenNodeDetail(data_type, data_type, {first * ele_per_blk}), max_perf1));
891	  GE_ASSERT_SUCCESS(ascendcperf::MaxPerf(GenNodeDetail(data_type, data_type, {kMaxRepeatTime}), max_perf2));
892	  GE_ASSERT_SUCCESS(ascendcperf::MaxPerf(GenNodeDetail(data_type, data_type, {repeat_tail}), max_perf3));
893	  GE_ASSERT_SUCCESS(
894	      ascendcperf::BlockReduceMaxPerf(GenNodeDetail(data_type, data_type, {first * ele_per_blk}), blockreducemax_perf));
895	  perf_res.pipe_res[PipeType::AIV_VEC] =
896	      GetPipeCost(adds_perf, PipeType::AIV_VEC) + blk_count * GetPipeCost(max_perf1, PipeType::AIV_VEC) +
897	      blk_pad * first_repeat * GetPipeCost(max_perf2, PipeType::AIV_VEC) +
898	      blk_pad * GetPipeCost(max_perf3, PipeType::AIV_VEC) + GetPipeCost(blockreducemax_perf, PipeType::AIV_VEC);
899	  return af::SUCCESS;
900	}
