1010	  比较复杂，目前先实现RA形式且isReuseSource=false的场景
1011	  ReduceSum在计算时会触发log2(first)次Add操作，由于目前symengine不支持，因此不建模
1012	  这会导致计算出的cycle数偏小(差不多少log2(first/2)*40cycle)
1013	*/
1014	af::Status ReduceSumPerf([[maybe_unused]] const std::vector<TensorShapeInfo> &input_shapes, PerfOutputInfo &perf_res) {
1015	  std::string data_type = input_shapes[0].data_type;
1016	  auto dims = input_shapes[0].dims;
1017	  GE_ASSERT_TRUE(dims.size() == 2U);
1018	  auto it = kBlkEleMap.find(input_shapes[0].data_type);
1019	  GE_ASSERT_TRUE(it != kBlkEleMap.end());
1020	  PerfOutputInfo adds_perf1;
1021	  PerfOutputInfo adds_perf2;
1022	  PerfOutputInfo add_perf1;
1023	  PerfOutputInfo add_perf2;
1024	  Expr first = dims[0];
1025	  Expr last = dims[1];
1026	  Expr split_k = (first / kSymTwo) * kSymTwo;
1027	  Expr tail = first - split_k;
1028	  Expr ele_per_blk = it->second;
1029	  Expr tail_pad = af::sym::Ceiling(tail / (tail + CreateExpr(1)));
1030	  Expr pad_last = af::sym::Ceiling(last / ele_per_blk) * ele_per_blk;
1031	  GE_ASSERT_SUCCESS(ascendcperf::AddsPerf(GenNodeDetail(data_type, data_type, {split_k * pad_last}), adds_perf1));
1032	  GE_ASSERT_SUCCESS(ascendcperf::AddPerf(GenNodeDetail(data_type, data_type, {tail * pad_last}), add_perf1));
1033	  GE_ASSERT_SUCCESS(
1034	      ascendcperf::AddPerf(GenNodeDetail(data_type, data_type, {(kSymTwo * split_k - kSymTwo) * pad_last}), add_perf2));
1035	  GE_ASSERT_SUCCESS(ascendcperf::AddsPerf(GenNodeDetail(data_type, data_type, {last}), adds_perf2));
1036	  perf_res.pipe_res[PipeType::AIV_VEC] =
1037	      tail_pad * GetPipeCost(adds_perf1, PipeType::AIV_VEC) + tail_pad * GetPipeCost(add_perf1, PipeType::AIV_VEC) +
1038	      GetPipeCost(add_perf2, PipeType::AIV_VEC) + GetPipeCost(adds_perf2, PipeType::AIV_VEC);
1039	  return af::SUCCESS;
1040	}
