1049	/*
1050	ReduceProdapi的性能公式：
1051	  比较复杂，目前先实现RA形式且isReuseSource=false的场景
1052	  ReduceProd在计算时会触发log2(first)次Mul操作，由于目前symengine不支持，因此不建模
1053	  这会导致计算出的cycle数偏小(差不多少log2(first/2)*40cycle)
1054	*/
1055	af::Status ReduceProdPerf([[maybe_unused]] const std::vector<TensorShapeInfo> &input_shapes, PerfOutputInfo &perf_res) {
1056	  std::string data_type = input_shapes[0].data_type;
1057	  auto dims = input_shapes[0].dims;
1058	  GE_ASSERT_TRUE(dims.size() == 2U);
1059	  auto it = kBlkEleMap.find(input_shapes[0].data_type);
1060	  GE_ASSERT_TRUE(it != kBlkEleMap.end());
1061	  PerfOutputInfo adds_perf1;
1062	  PerfOutputInfo adds_perf2;
1063	  PerfOutputInfo mul_perf1;
1064	  PerfOutputInfo mul_perf2;
1065	  Expr first = dims[0];
1066	  Expr last = dims[1];
1067	  Expr split_k = (first / kSymTwo) * kSymTwo;
1068	  Expr remain = first - split_k;
1069	  Expr remain_pad = af::sym::Ceiling(remain / (remain + CreateExpr(1)));
1070	  Expr ele_per_blk = it->second;
1071	  Expr pad_last = af::sym::Ceiling(last / ele_per_blk) * ele_per_blk;
1072	  GE_ASSERT_SUCCESS(ascendcperf::AddsPerf(GenNodeDetail(data_type, data_type, {pad_last * split_k}), adds_perf1));
1073	  GE_ASSERT_SUCCESS(ascendcperf::MulPerf(GenNodeDetail(data_type, data_type, {pad_last * remain}), mul_perf1));
1074	  GE_ASSERT_SUCCESS(
1075	      ascendcperf::MulPerf(GenNodeDetail(data_type, data_type, {(kSymTwo * split_k - kSymTwo) * pad_last}), mul_perf2));
1076	  GE_ASSERT_SUCCESS(ascendcperf::AddsPerf(GenNodeDetail(data_type, data_type, {last}), adds_perf2));
1077	  perf_res.pipe_res[PipeType::AIV_VEC] =
1078	      remain_pad * GetPipeCost(adds_perf1, PipeType::AIV_VEC) + remain_pad * GetPipeCost(mul_perf1, PipeType::AIV_VEC) +
1079	      GetPipeCost(mul_perf2, PipeType::AIV_VEC) + GetPipeCost(adds_perf2, PipeType::AIV_VEC);
1080	  return af::SUCCESS;
1081	}
