1234	af::Status WhereBasePerf(const NodeDetail &node_info, PerfOutputInfo &perf) {
1235	  GELOGD("WhereBasePerf: node info is %s.", node_info.ToString().c_str());
1236	  Expr one_rpt_size = kRptSizeFloat;
1237	  Expr size = node_info.input_dims[kNumZero];
1238	  GELOGD("one_rpt_size: [%s], dim size is [%s]", af::SymbolicUtils::ToString(one_rpt_size).c_str(),
1239	         af::SymbolicUtils::ToString(size).c_str());
1240	  Expr max_do_size = kMaxRepeatTime * one_rpt_size;  // 16320
1241	  GELOGD("max_do_size is [%s]", af::SymbolicUtils::ToString(max_do_size).c_str());
1242	  Expr branch_max_repeat_cost = CastBeforeSelectPerf(node_info.input_dtype[kNumOne], node_info.input_dtype[kNumTwo],
1243	                                                     node_info.output_dtype[kNumZero], max_do_size, kMaxRepeatTime);
1244	  GELOGD("branch_max_repeat_cost is [%s]", af::SymbolicUtils::ToString(branch_max_repeat_cost).c_str());
1245	  Expr left_repeat_times =
1246	      (size - max_do_size) / kSymFour;  // 三元表达式的max_do_size <= size可以保证left_repeat_times >= 0
1247	  Expr left_sign =
1248	      af::sym::Ceiling(left_repeat_times / (left_repeat_times + af::sym::kSymbolOne));  // 判断left_repeat_times是否为0
1249	  Expr left_do_size = left_repeat_times * kRptSizeFloat;
1250	  GELOGD("left_sign is [%s], left_repeat_times is [%s], left_do_size is [%s]",
1251	         af::SymbolicUtils::ToString(left_sign).c_str(), af::SymbolicUtils::ToString(left_repeat_times).c_str(),
1252	         af::SymbolicUtils::ToString(left_do_size).c_str());
1253	  Expr branch_left_repeat_cost =
1254	      CastBeforeSelectPerf(node_info.input_dtype[kNumOne], node_info.input_dtype[kNumTwo],
1255	                           node_info.output_dtype[kNumZero], left_do_size, left_repeat_times);
1256	  GELOGD("branch_left_repeat_cost is [%s]", af::SymbolicUtils::ToString(branch_left_repeat_cost).c_str());
1257	  Expr repeat_times = size / kSymFour;
1258	  Expr do_size = repeat_times * kRptSizeFloat;
1259	  GELOGD("repeat_times is [%s], do_size is [%s]", af::SymbolicUtils::ToString(repeat_times).c_str(),
1260	         af::SymbolicUtils::ToString(do_size).c_str());
1261	  Expr branch_small_repeat_cost = CastBeforeSelectPerf(node_info.input_dtype[kNumOne], node_info.input_dtype[kNumTwo],
1262	                                                       node_info.output_dtype[kNumZero], do_size, repeat_times);
1263	  GELOGD("branch_small_repeat_cost is [%s]", af::SymbolicUtils::ToString(branch_small_repeat_cost).c_str());
1264	  Expr res = CreateExpr("where_base_node");
1265	  TernaryOp ternary_op =
1266	      TernaryOp(CondType::K_LE, max_do_size, size, branch_max_repeat_cost + left_sign * branch_left_repeat_cost,
1267	                branch_small_repeat_cost);
1268	  ternary_op.SetVariable(res);
1269	  perf.ternary_ops[res] = ternary_op;
1270	  perf.pipe_res[PipeType::AIV_VEC] = res;
1271	  return af::SUCCESS;
1272	}
