1274	af::Status WhereExtendPerf(const NodeDetail &node_info, PerfOutputInfo &perf) {
1275	  GELOGD("WhereExtendPerf: node info is %s.", node_info.ToString().c_str());
1276	  Expr one_rpt_size = kRptSizeFloat;
1277	  GELOGD("one_rpt_size: [%s]", af::SymbolicUtils::ToString(one_rpt_size).c_str());
1278	  Expr first_axis = node_info.input_dims[kNumZero];
1279	  Expr last_axis = node_info.input_dims[kNumOne];
1280	  GELOGD("first_axis is [%s], last_axis is [%s]", af::SymbolicUtils::ToString(first_axis).c_str(),
1281	         af::SymbolicUtils::ToString(last_axis).c_str());
1282	  Expr element_extent = af::sym::Floor(last_axis / one_rpt_size);
1283	  Expr max_buf_size = af::sym::Div(kTempBufSize, kSymEight);
1284	  Expr max_buf_rpt_num = af::sym::Div(max_buf_size, one_rpt_size);
1285	  Expr max_do_rpt_num = af::sym::Min(kMaxRepeatTime, max_buf_rpt_num);
1286	  GELOGD("max_do_rpt_num is [%s]", af::SymbolicUtils::ToString(max_do_rpt_num).c_str());
1287	  GE_ASSERT_TRUE(max_do_rpt_num != af::sym::kSymbolZero);
1288	  Expr repeat_throw_for_extent = af::sym::Floor(first_axis / max_do_rpt_num);
1289	  Expr repeat_reminder = af::sym::Mod(first_axis, max_do_rpt_num);
1290	  Expr repeat_sign = af::sym::Ceiling(repeat_reminder / (repeat_reminder + af::sym::kSymbolOne));
1291	  GELOGD("element_extent is [%s], repeat_sign is [%s], repeat_reminder is [%s], repeat_throw_for_extent is [%s]",
1292	         af::SymbolicUtils::ToString(element_extent).c_str(), af::SymbolicUtils::ToString(repeat_sign).c_str(),
1293	         af::SymbolicUtils::ToString(repeat_reminder).c_str(),
1294	         af::SymbolicUtils::ToString(repeat_throw_for_extent).c_str());
1295	  PerfOutputInfo cast_select_perf1;
1296	  PerfOutputInfo cast_select_perf2;
1297	  GE_ASSERT_SUCCESS(CastSelectNormalPerf(node_info.input_dtype[kNumOne], node_info.input_dtype[kNumTwo],
1298	                                         node_info.output_dtype[kNumZero], max_do_rpt_num, cast_select_perf1));
1299	  GELOGD("cast_select_perf1 is [%s]",
1300	         af::SymbolicUtils::ToString(GetPipeCost(cast_select_perf1, PipeType::AIV_VEC)).c_str());
1301	  GE_ASSERT_SUCCESS(CastSelectNormalPerf(node_info.input_dtype[kNumOne], node_info.input_dtype[kNumTwo],
1302	                                         node_info.output_dtype[kNumZero], repeat_reminder, cast_select_perf2));
1303	  GELOGD("cast_select_perf2 is [%s]",
1304	         af::SymbolicUtils::ToString(GetPipeCost(cast_select_perf2, PipeType::AIV_VEC)).c_str());
1305	  perf.pipe_res[PipeType::AIV_VEC] =
1306	      element_extent * (repeat_throw_for_extent * GetPipeCost(cast_select_perf1, PipeType::AIV_VEC) +
1307	                        repeat_sign * GetPipeCost(cast_select_perf2, PipeType::AIV_VEC));
1308	  return af::SUCCESS;
1309	}
