1311	af::Status WhereApi([[maybe_unused]] const std::vector<TensorShapeInfo> &input_shapes,
1312	                    [[maybe_unused]] const std::vector<TensorShapeInfo> &output_shapes,
1313	                    [[maybe_unused]] const NodeInfo &node, PerfOutputInfo &perf_res) {
1314	  auto const &node_ptr = node.node_ptr;
1315	  GE_ASSERT_TRUE(input_shapes.size() >= 3U && !output_shapes.empty());
1316	  auto merged_output_shapes = output_shapes[0];
1317	  GE_ASSERT_SUCCESS(MergeTensorContinuousDims(node_ptr, GetNodeOutTensorName(node_ptr, 0), merged_output_shapes));
1318	  NodeDetail node_info;
1319	  Expr outer_repeat;
1320	  vector<Expr> used_dims;
1321	  GE_ASSERT_SUCCESS(GetOuterParams(merged_output_shapes.dims, outer_repeat, used_dims));
1322	  GE_ASSERT_SUCCESS(SetNodeDetail(input_shapes, output_shapes, node_info));
1323	  GE_ASSERT_SUCCESS(SetDims(used_dims, node_info));
1324	  auto input_dims_size = node_info.input_dims.size();
1325	  GELOGD("input_dims_size is {%u}", input_dims_size);
