  GE_ASSERT_SUCCESS(ascendcperf::DuplicatePerf(duplicate_node, duplicate_perf), "Gen Duplicate perf Failed.");
  perf_res.pipe_res[PipeType::AIV_VEC] = GetPipeCost(duplicate_perf, PipeType::AIV_VEC);
