36	void UpdateDim(const std::vector<Expr> &stride, std::vector<Expr> &dims) {
37	  for (size_t i = stride.size() - 1UL; i >= 1UL; --i) {
38	    if (stride[i] == 0) {
39	      continue;
40	    }
41	    size_t cur = i - 1UL;
42	    while (cur >= 1UL && stride[cur] == 0) {
43	      --cur;
44	    }
45	    if (stride[cur] != 0) {
46	      dims[i] = stride[cur];
47	    }
48	    break;
49	  }
50	}
