71	// 辅助函数：应用变量替换
72	static void ApplyVariableReplacement(const std::vector<Expr> &update_vars,
73	                                     const std::vector<std::pair<Expr, Expr>> &replace_vars,
74	                                     std::map<Expr, TernaryOp, ExprCmp> &ternary_ops) {
75	  for (const auto &var : update_vars) {
76	    ternary_ops[var].Replace(replace_vars);
77	    ternary_ops[var].UpdateRelatedVars(replace_vars);
78	    GELOGD("The value of [%s] is [%s]", Str(var).c_str(), ternary_ops[var].GetTernaryOpStr().c_str());
79	  }
80	}
