207	bool CheckInclude(const std::vector<std::string> &cur_orig, const std::vector<std::string> &check_orig) {
208	  std::map<std::string, int32_t> rec_num;
209	  if (check_orig.size() <= cur_orig.size()) {
210	    return false;
211	  }
212	  for (const auto &name : cur_orig) {
213	    rec_num[name]++;
214	  }
215	  for (const auto &name : check_orig) {
216	    rec_num[name]--;
217	  }
218	  for (const auto &pair : rec_num) {
219	    if (pair.second > 0) {
220	      return false;
221	    }
222	  }
223	  return true;
224	}
