226	/*
227	此函数用于检测是否触发尾块计算逻辑：
228	1) 向量化轴中只存在一根切分轴
229	2) 存在某根循环轴，他的原始轴包含了这根切分轴所有的原始轴
230	注：
231	1. 对于同时切block和tile的场景，只会存在一个尾块
232	2. 存在一个尾块的场景，仅在核数为1的时候性能公式估计不准
233	3. 多核切分策略保证优先分核，而不会分出尾块，所以保证了不会出现上述情况
234	*/
235	bool CheckSingleCut(const NodeInfo &node) {
236	  std::set<const SubAxis *> cut_axes;
237	  for (const auto &input : node.inputs) {
238	    for (const auto &dim : input->dim_info) {
239	      if (dim->axis_type == AxisPosition::INNER) {
240	        cut_axes.insert(dim);
241	      }
242	    }
243	  }
244	  for (const auto &output : node.outputs) {
245	    for (const auto &dim : output->dim_info) {
246	      if (dim->axis_type == AxisPosition::INNER) {
247	        cut_axes.insert(dim);
248	      }
249	    }
250	  }
251	  GELOGD("Node [%s] has [%zu] cut.", node.name.c_str(), cut_axes.size());
252	  if (cut_axes.size() != 1) {
253	    GELOGD("Single cut unsatisfied for node[%s].", node.name.c_str());
254	    return false;
255	  }
256	  const SubAxis *cut_axis = *cut_axes.begin();
257	  for (const auto &axis : node.loop_axes) {
258	    if (CheckInclude(cut_axis->orig_axis_name, axis->orig_axis_name)) {
259	      GELOGD("The merged axis [%s] has the outer axis of [%s].", axis->name.c_str(), cut_axis->name.c_str());
260	      return true;
261	    }
262	  }
263	  GELOGD("Cannot find merged outer axis for [%s] within loop axes.", cut_axis->name.c_str());
264	  return false;
265	}
