269	  std::vector<Expr> ret;
270	  for (const auto &dim : tensor->dim_info) {
271	    if (dim->axis_type != AxisPosition::INNER) {
272	      ret.emplace_back(dim->repeat);
273	    } else {
274	      GE_ASSERT_TRUE(dim->parent_axis.size() == 1);
275	      Expr parent_size = dim->parent_axis[0]->repeat;
276	      ret.emplace_back(GetTailSize(parent_size, dim->repeat, ternary_ops));
277	    }
278	  }
279	  return ret;
280	}
