459	af::Status PipePerfExpr::AddTailPerf(const Expr &tail_exe_time, const Expr &node_exe_times,
460	                                     const std::map<PipeType, Expr> &node_tail_perf, PerfAddContext &tail_ctx) {
461	  Expr core_exe_time = node_exe_times - tail_exe_time;
462	  GELOGD("The exe time of the tail block is [%s], the exe time of the other block is [%s].",
463	         af::SymbolicUtils::ToString(tail_exe_time).c_str(), af::SymbolicUtils::ToString(core_exe_time).c_str());
464	
465	  // 为 core perf 创建临时 context（使用 node_perf）
466	  PerfAddContext core_ctx(tail_ctx.node_perf, tail_ctx.pipe_costs, tail_ctx.ternary_ops, tail_ctx.expr_prefix);
467	  GE_ASSERT_SUCCESS(AddPerf(core_exe_time, "core_contrib", core_ctx));
468	
469	  // 为 tail perf 创建临时 context（使用 node_tail_perf）
470	  PerfAddContext tail_ctx_adapter(node_tail_perf, tail_ctx.pipe_costs, tail_ctx.ternary_ops, tail_ctx.expr_prefix);
471	  GE_ASSERT_SUCCESS(AddPerf(tail_exe_time, "tail_contrib", tail_ctx_adapter));
472	
473	  return af::SUCCESS;
474	}
