476	af::Status PipePerfExpr::AddPerf(const Expr &node_exe_times, const std::string &contrib_suffix, PerfAddContext &ctx) {
477	  for (const auto &pair : ctx.node_perf) {
478	    const auto &pipe_type_iter = PipeType2Str.find(pair.first);
479	    GE_ASSERT_TRUE(pipe_type_iter != PipeType2Str.end(), "Get pipe type str failed.");
480	    GELOGD("Get perf times [%s] at [%s], exe_time [%s]", pair.second.Str().get(), pipe_type_iter->second.c_str(),
481	           af::SymbolicUtils::ToString(node_exe_times).c_str());
482	    Expr pipe_cost = af::sym::Mul(node_exe_times, pair.second);
483	    std::string var_name = ctx.expr_prefix + "_" + pipe_type_iter->second + "_" + contrib_suffix;
484	    Expr contrib_var;
485	    GetPerfVar(var_name, contrib_var, ctx.ternary_ops);
486	    TernaryOp contrib_op(pipe_cost);
487	    contrib_op.SetVariable(contrib_var);
488	    contrib_op.SetDescription(GetContribDescription(pipe_type_iter->second, contrib_suffix));
489	    ctx.ternary_ops[contrib_var] = std::move(contrib_op);
490	    auto iter = ctx.pipe_costs.find(pair.first);
491	    if (iter == ctx.pipe_costs.end()) {
492	      ctx.pipe_costs[pair.first] = contrib_var;
493	    } else {
494	      ctx.pipe_costs[pair.first] = contrib_var + ctx.pipe_costs[pair.first];
495	    }
496	  }
497	  return af::SUCCESS;
498	}
