536	af::Status PipePerfExpr::UpdatePipeHead(std::map<PipeType, Expr> &pipe_costs,
537	                                        std::map<Expr, TernaryOp, ExprCmp> &ternary_ops) const {
538	  for (auto &pair : pipe_costs) {
539	    auto pipe_head_perf_func = GetPipeHeadPerfFunc(pair.first);
540	    GE_ASSERT_NOTNULL(pipe_head_perf_func);
541	    Expr pipe_head = pipe_head_perf_func(tuning_space_->node_infos, ternary_ops);
542	    pair.second = af::sym::Add(pair.second, pipe_head);
543	  }
544	  return af::SUCCESS;
545	}
