547	af::Status PipePerfExpr::GetPerfExpr(std::map<PipeType, Expr> &pipe_costs,
548	                                     std::map<Expr, TernaryOp, ExprCmp> &ternary_ops, Expr &head_cost) {
549	  std::vector<PerfBreakdownGroup> perf_breakdowns;
