553	af::Status PipePerfExpr::GetPerfExpr(std::map<PipeType, Expr> &pipe_costs,
554	                                     std::map<Expr, TernaryOp, ExprCmp> &ternary_ops,
555	                                     std::vector<PerfBreakdownGroup> &perf_breakdowns, Expr &head_cost) {
556	  ExeTimePassManager exe_time_mgr(tuning_space_);
557	
558	  std::unordered_set<std::string> skip_node_types = {kData, kWorkspace, kOutput, kTbufData, kScalar};
559	  for (const auto &node : tuning_space_->node_infos) {
560	    if (skip_node_types.count(node.node_type) != 0U) {
561	      continue;
562	    }
563	
564	    // 获取节点执行时间
565	    TernaryOp node_exe_times;
566	    GE_ASSERT_SUCCESS(GetNodeExeTime(node, exe_time_mgr, node_exe_times), "Get node [%s] exec times failed.",
567	                      node.name.c_str());
568	    Expr exe_var = node_exe_times.GetVariable();
569	    ternary_ops[exe_var] = node_exe_times;
570	    GELOGD("Get node [%s] exe times %s=[%s]", node.name.c_str(), exe_var.Serialize().get(),
571	           node_exe_times.GetTernaryOpStr().c_str());
572	
573	    // 获取节点性能
574	    std::map<PipeType, Expr> node_perf;
575	    GE_ASSERT_SUCCESS(GetNodePerfInternal(node, node_perf, ternary_ops, perf_breakdowns),
576	                      "Get node [%s][%s] perf failed.", node.name.c_str(), node.node_type.c_str());
577	
578	    // 添加性能到总成本
579	    GE_ASSERT_SUCCESS(AddNodePerfToPipeCost(node, exe_var, node_perf, pipe_costs, ternary_ops, perf_breakdowns));
580	  }
581	
582	  GE_ASSERT_SUCCESS(UpdatePipeHead(pipe_costs, ternary_ops));
583	  GE_ASSERT_SUCCESS(GetOpHeadCost(head_cost));
584	  return af::SUCCESS;
585	}
