587	// 获取节点性能（内部方法，包含VectorFunc特殊处理）
588	af::Status PipePerfExpr::GetNodePerfInternal(const NodeInfo &node, std::map<PipeType, Expr> &node_perf,
589	                                             std::map<Expr, TernaryOp, ExprCmp> &ternary_ops,
590	                                             std::vector<PerfBreakdownGroup> &perf_breakdowns, bool tail_shape) const {
591	  if (node.node_type == kVectorFunc) {
592	    // VectorFunc节点特殊处理
593	    std::vector<NodePerfInfo> node_perf_infos;
594	    std::vector<Expr> vector_func_dims;
595	    GE_ASSERT_SUCCESS(GetVectorFuncDims(node, vector_func_dims), "Get vector function dims failed, node = %s %s",
596	                      node.name.c_str(), node.node_type.c_str());
597	    GE_ASSERT_SUCCESS(ConvertToPerfInfo(node.sub_nodes_infos, node_perf_infos, vector_func_dims),
598	                      "Convert to perf info failed, node = %s %s", node.name.c_str(), node.node_type.c_str());
599	    Expr res;
600	    GE_ASSERT_SUCCESS(VfPerfUtils::GetVectorFunctionPerf(node_perf_infos, node.vector_func_params, ternary_ops, res),
601	                      "Get vector function perf failed, node = %s %s.", node.name.c_str(), node.node_type.c_str());
602	
603	    // 为VectorFunc节点创建ternary_ops条目
604	    NodeExprId node_expr_id = BuildNodeExprId(node);
605	    std::string expr_prefix = node_expr_id.GetExprVarPrefix();
606	    std::string full_desc = node_expr_id.GetVarPrefix();
607	
608	    auto it = PipeType2Str.find(PipeType::AIV_VEC);
609	    if (it != PipeType2Str.end()) {
610	      std::string var_name = expr_prefix + "_" + it->second + "_perf";
611	      std::string desc = full_desc + "_" + it->second + "_perf";
612	      Expr perf_expr;
613	      GetPerfVar(var_name, perf_expr, ternary_ops);
614	      ternary_ops[perf_expr] = TernaryOp(res);
615	      ternary_ops[perf_expr].SetVariable(perf_expr);
616	      ternary_ops[perf_expr].SetDescription(desc);
617	      node_perf[PipeType::AIV_VEC] = perf_expr;
618	    } else {
619	      node_perf[PipeType::AIV_VEC] = res;
620	    }
621	  } else {
622	    // 普通节点
623	    GE_ASSERT_SUCCESS(GetNodePerf(node, node_perf, ternary_ops, perf_breakdowns, tail_shape),
624	                      "Get node [%s][%s] perf failed.", node.name.c_str(), node.node_type.c_str());
625	  }
626	  return af::SUCCESS;
627	}
