27	Expr PerfParamTableV1::GetMTE2PipeHead(const std::vector<NodeInfo> &node_infos,
28	                                       std::map<Expr, TernaryOp, ExprCmp> &ternary_ops) {
29	  Expr mte2_pipe_head;
30	  Expr max_data_size = af::sym::kSymbolZero;
31	  for (const auto &node : node_infos) {
32	    if (node.node_type == kLoad) {
33	      if (node.inputs.size() != 1) {
34	        GELOGW("Got node %s input size %zu is not 1.", node.name.c_str(), node.inputs.size());
35	        continue;
36	      }
37	      auto dims = node.inputs[0]->repeat;
38	      Expr dim_product =
39	          std::accumulate(dims.begin(), dims.end(), CreateExpr(1), [](const Expr &a, const Expr &b) { return a * b; });
40	      Expr data_size = dim_product * CreateExpr(node.inputs[0]->data_type_size);
41	      if (max_data_size != af::sym::kSymbolZero) {
42	        max_data_size = af::sym::Max(data_size, max_data_size);
43	      } else {
44	        max_data_size = data_size;
45	      }
46	    }
47	  }
48	  const auto block_dim = CreateExpr("block_dim");
49	  Expr small_head_cost = block_dim * kMte2PipeHeadSmallK + kMte2PipeHeadSmallB;
50	  Expr normal_head_cost = block_dim * kMte2PipeHeadNormalK + kMte2PipeHeadNormalB;
51	  if (max_data_size.IsConstExpr()) {
52	    uint64_t datasize;
53	    max_data_size.GetConstValue(datasize);
54	    if (datasize >= kLoadThreshold) {
55	      mte2_pipe_head = normal_head_cost;
56	    } else {
57	      mte2_pipe_head = small_head_cost;
58	    }
59	  } else {
60	    GetPerfVar("mte2_pipe_head", mte2_pipe_head, ternary_ops);
61	    TernaryOp ternary_op = TernaryOp(CondType::K_LT, max_data_size, kMTE2Thres, small_head_cost, normal_head_cost);
62	    ternary_op.SetVariable(mte2_pipe_head);
63	    ternary_ops[mte2_pipe_head] = ternary_op;
64	  }
65	  return mte2_pipe_head;
66	}
